import{_ as l,C as n,o as d,c as e,j as i,a as o,E as r,a3 as s}from"./chunks/framework.C6R8kWFE.js";const P=JSON.parse(`{"title":"12-dars (Mentor). Bulutli xizmatlar va onlayn hamkorlik vositalari (2-qism): onlayn hujjatlar va vazifalarni boshqarish","description":"","frontmatter":{"title":"12-dars (Mentor). Bulutli xizmatlar va onlayn hamkorlik vositalari (2-qism): onlayn hujjatlar va vazifalarni boshqarish","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":4,"link":"/mentor/8-sinf-cs/hafta-04/"},"g":12,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (2-qism): onlayn hujjatlar va vazifalarni boshqarish","lead":"To'rt kishi bitta taqdimotni qanday birga tayyorlaydi? Faylni bir-biriga 10 marta yuborib emas! Bugun bitta onlayn hujjatda birga yozamiz, izoh qoldiramiz va Trello doskasida vazifalarni bo'lishamiz.","slide":"/slaydlar/8-sinf-cs/hafta-04/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-04/dars-3-test.html","student_link":"/8-sinf-cs/hafta-04/dars-3","tabs":[{"g":10,"link":"/mentor/8-sinf-cs/hafta-04/dars-1","current":false},{"g":11,"link":"/mentor/8-sinf-cs/hafta-04/dars-2","current":false},{"g":12,"link":"/mentor/8-sinf-cs/hafta-04/dars-3","current":true}],"prev":{"g":11,"title":"Bulutli xizmatlar va onlayn hamkorlik vositalari (1-qism): bulutli saqlash, yuklash va ulashish","link":"/mentor/8-sinf-cs/hafta-04/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-04/dars-3.md","filePath":"mentor/8-sinf-cs/hafta-04/dars-3.md"}`),h={name:"mentor/8-sinf-cs/hafta-04/dars-3.md"},u={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},m={class:"blk"},b={id:"_2-dars-konspekti",tabindex:"-1"},k={class:"blk"},y={id:"_3-amaliy-mashg-ulotlar",tabindex:"-1"},c={class:"blk"},v={id:"_4-tezkor-savollar-checklist",tabindex:"-1"},q={class:"blk"},p={id:"_5-kuchli-o-quvchi-uchun-qo-shimcha",tabindex:"-1"},f={class:"blk"},j={id:"_6-mentor-uchun-eslatmalar",tabindex:"-1"};function z(x,a,_,T,S,D){const t=n("Icon");return d(),e("div",null,[a[18]||(a[18]=i("p",null,[i("strong",null,"Hafta:"),o(" 4 · "),i("strong",null,"Davomiyligi:"),o(" 80 daqiqa · "),i("strong",null,"Turi:"),o(" amaliyot (guruhli ish) · "),i("strong",null,"II-bob"),o(", 6-dars (hafta ichida 3-dars)")],-1)),a[19]||(a[19]=i("blockquote",null,[i("p",null,"Manba: o'quv dasturi, 11-mavzu (davomi): «Onlayn hujjatlar bilan ishlash: Google Docs, Sheets, Slides va Microsoft 365. Fayllarni yuklash, ulashish va ruxsatlarni boshqarish. Onlayn hamkorlik va vazifalarni boshqarish vositalari: Microsoft To Do, Google Tasks, Trello.» Dasturda metod: hamkorlikda o'rganish (Peer Learning) — bulutli xizmatlardan foydalanish va guruhli loyihalarda. Ushbu dars — mavzuning 2-qismi (amaliy); 3-qism 5-haftadagi 13-darsda.")],-1)),i("div",u,[i("h2",g,[r(t,{name:"file-text"}),a[0]||(a[0]=o(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=s('<p><strong>Maqsad:</strong> o&#39;quvchilar onlayn hujjat (Docs, Sheets, Slides va Microsoft 365) yaratadi, uni jamoadoshlar bilan ulashib, bir vaqtda tahrirlaydi, izoh va versiya tarixidan foydalanadi; vazifalarni boshqarish vositalari (Microsoft To Do, Google Tasks, Trello) yordamida guruh ishini rejalashtiradi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Google Docs, Sheets, Slides va ularning Microsoft 365 dagi juftlarini (Word, Excel, PowerPoint onlayn) farqlaydi.</li><li>Hujjatni ulashadi va jamoadoshlar bilan bir vaqtda tahrirlaydi.</li><li>Izoh (comment) qoldiradi, unga javob beradi va versiya tarixini ochadi.</li><li>Trello doskasida «Qilinadi → Jarayonda → Bajarildi» ustunlari bilan vazifalarni boshqaradi.</li><li>To Do, Google Tasks va Trello dan qaysi biri shaxsiy, qaysi biri jamoaviy ish uchun qulayligini tushuntiradi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>11-dars: ruxsat darajalari bo&#39;yicha 3 ta tezkor savol. Muammo: «4 kishi bitta taqdimotni qanday birga tayyorlaydi?»</td></tr><tr><td>10–30 daq</td><td>Yangi mavzu</td><td>Onlayn hujjatlar, Microsoft 365, birgalikda tahrir, izoh, versiya tarixi, vazifa vositalari</td></tr><tr><td>30–35 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>35–68 daq</td><td>Guruhli amaliyot</td><td>«Sinf gazetasi» mini-loyihasi: Docs/Slides + Sheets + Trello doskasi</td></tr><tr><td>68–75 daq</td><td>Tezkor nazorat</td><td>5 ta savol + mini-viktorina</td></tr><tr><td>75–80 daq</td><td>Xulosa, refleksiya va uyga vazifa</td><td>Guruhlar natijasi, uyga vazifa</td></tr></tbody></table><hr>',5))]),i("div",m,[i("h2",b,[r(t,{name:"file-text"}),a[3]||(a[3]=o(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=s(`<h3 id="_2-1-onlayn-hujjat-nima" tabindex="-1">2.1. Onlayn hujjat nima? <a class="header-anchor" href="#_2-1-onlayn-hujjat-nima" aria-label="Permalink to &quot;2.1. Onlayn hujjat nima?&quot;">​</a></h3><p><strong>Onlayn hujjat</strong> — kompyuterga dastur o&#39;rnatmasdan, brauzerda yaratiladigan va bulutda saqlanadigan hujjat. U avtomatik saqlanadi («Saqlash» tugmasi kerak emas) va boshqalar bilan bir vaqtda tahrirlanadi.</p><table tabindex="0"><thead><tr><th>Vazifa</th><th>Google</th><th>Microsoft 365 (onlayn)</th></tr></thead><tbody><tr><td>Matnli hujjat (referat, insho)</td><td><strong>Google Docs</strong></td><td>Word</td></tr><tr><td>Jadval, hisob-kitob</td><td><strong>Google Sheets</strong></td><td>Excel</td></tr><tr><td>Taqdimot</td><td><strong>Google Slides</strong></td><td>PowerPoint</td></tr><tr><td>Saqlash joyi</td><td>Google Drive</td><td>OneDrive</td></tr></tbody></table><p>Google xizmatlari Google akkaunti bilan bepul; Microsoft 365 ning onlayn versiyalari (<code>office.com</code>) Microsoft akkaunti bilan bepul ishlatiladi, to&#39;liq kompyuter dasturlari esa odatda pullik obuna bilan.</p><h3 id="_2-2-hujjat-yaratish-va-ulashish" tabindex="-1">2.2. Hujjat yaratish va ulashish <a class="header-anchor" href="#_2-2-hujjat-yaratish-va-ulashish" aria-label="Permalink to &quot;2.2. Hujjat yaratish va ulashish&quot;">​</a></h3><ol><li><code>drive.google.com</code> → <strong>Yangi</strong> → <strong>Google Docs</strong> (yoki Sheets, Slides).</li><li>Chap yuqorida «Nomsiz hujjat» ni bosib, ma&#39;noli nom bering: <code>Sinf gazetasi — 4-hafta</code>.</li><li>O&#39;ng yuqorida <strong>Ulashish (Share)</strong> → jamoadoshlar emaili → <strong>Muharrir</strong> → <strong>Yuborish</strong>.</li></ol><p>Microsoft 365 da: <code>office.com</code> → <strong>Word</strong> → <strong>Yangi bo&#39;sh hujjat</strong> → o&#39;ng yuqorida <strong>Ulashish</strong>.</p><h3 id="_2-3-birgalikda-tahrirlash" tabindex="-1">2.3. Birgalikda tahrirlash <a class="header-anchor" href="#_2-3-birgalikda-tahrirlash" aria-label="Permalink to &quot;2.3. Birgalikda tahrirlash&quot;">​</a></h3><p>Bir hujjatni bir necha kishi bir vaqtda ochganda:</p><ul><li>o&#39;ng yuqorida jamoadoshlarning <strong>avatarlari</strong> (rasmcha yoki bosh harf) ko&#39;rinadi;</li><li>har bir odamning <strong>kursori o&#39;z rangida</strong> ko&#39;rinadi — kim qayerda yozayotgani bilinadi;</li><li>o&#39;zgarishlar bir necha soniyada hammada paydo bo&#39;ladi, hammasi avtomatik saqlanadi.</li></ul><p>Qoidalar: oldindan kim qaysi qismni yozishini kelishib oling, birovning matnini ogohlantirmasdan o&#39;chirmang.</p><h3 id="_2-4-izohlar-comments" tabindex="-1">2.4. Izohlar (comments) <a class="header-anchor" href="#_2-4-izohlar-comments" aria-label="Permalink to &quot;2.4. Izohlar (comments)&quot;">​</a></h3><p><strong>Izoh</strong> — matnning o&#39;zini o&#39;zgartirmasdan, uning yoniga yoziladigan fikr yoki savol.</p><ul><li>Matnni belgilang → <strong>Izoh qo&#39;shish</strong> belgisi (yoki <code>Ctrl + Alt + M</code>) → fikr yozing → <strong>Izoh</strong>.</li><li>Izohda <code>@</code> va jamoadosh emailini yozsangiz, unga xabar boradi.</li><li>Masala hal bo&#39;lgach, <strong>Hal qilindi (Resolve)</strong> bosiladi — izoh yashiriladi.</li></ul><p>Google Docs da yana <strong>Taklif rejimi (Suggesting)</strong> bor: siz yozgan o&#39;zgarish rangli belgilanadi, hujjat egasi uni qabul qiladi yoki rad etadi.</p><h3 id="_2-5-versiya-tarixi" tabindex="-1">2.5. Versiya tarixi <a class="header-anchor" href="#_2-5-versiya-tarixi" aria-label="Permalink to &quot;2.5. Versiya tarixi&quot;">​</a></h3><p>Hujjat har bir o&#39;zgarishni eslab qoladi. <strong>Fayl → Versiyalar tarixi → Versiyalar tarixini ko&#39;rish</strong> (<code>Ctrl + Alt + Shift + H</code>): kim, qachon, nimani o&#39;zgartirgani ko&#39;rinadi va kerak bo&#39;lsa eski versiyani tiklash mumkin.</p><blockquote><p>Jamoadosh xato bilan yarim matnni o&#39;chirib yubordi? Vahima qilmang — versiya tarixidan oldingi holatni tiklang.</p></blockquote><h3 id="_2-6-google-sheets-jamoaviy-jadval" tabindex="-1">2.6. Google Sheets: jamoaviy jadval <a class="header-anchor" href="#_2-6-google-sheets-jamoaviy-jadval" aria-label="Permalink to &quot;2.6. Google Sheets: jamoaviy jadval&quot;">​</a></h3><p>Sheets da guruh topshiriqlar ro&#39;yxati yoki byudjet yuritiladi. Eng oddiy formula — yig&#39;indi:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>A1: Material    B1: Narx (so&#39;m)</span></span>
<span class="line"><span>A2: Qog&#39;oz      B2: 15000</span></span>
<span class="line"><span>A3: Marker      B3: 12000</span></span>
<span class="line"><span>A4: Jami        B4: =SUM(B2:B3)      -&gt; 27000</span></span></code></pre></div><p>Formula <code>=</code> bilan boshlanadi; <code>B2:B3</code> — B2 dan B3 gacha bo&#39;lgan kataklar.</p><h3 id="_2-7-vazifalarni-boshqarish-vositalari" tabindex="-1">2.7. Vazifalarni boshqarish vositalari <a class="header-anchor" href="#_2-7-vazifalarni-boshqarish-vositalari" aria-label="Permalink to &quot;2.7. Vazifalarni boshqarish vositalari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vosita</th><th>Kompaniya</th><th>Asosiy g&#39;oya</th><th>Qulay holat</th></tr></thead><tbody><tr><td><strong>Microsoft To Do</strong></td><td>Microsoft</td><td>ro&#39;yxatlar, «Mening kunim», muddat va eslatma</td><td>shaxsiy kundalik ishlar, oddiy umumiy ro&#39;yxat</td></tr><tr><td><strong>Google Tasks</strong></td><td>Google</td><td>Gmail va Google Calendar ichidagi oddiy vazifalar ro&#39;yxati, muddat</td><td>shaxsiy ishlar, kalendar bilan bog&#39;liq vazifalar</td></tr><tr><td><strong>Trello</strong></td><td>Atlassian</td><td><strong>doska → ro&#39;yxat (ustun) → karta</strong></td><td>jamoaviy loyiha, kim nima qilayotganini ko&#39;rish</td></tr></tbody></table><h3 id="_2-8-trello-doska-ro-yxat-karta" tabindex="-1">2.8. Trello: doska, ro&#39;yxat, karta <a class="header-anchor" href="#_2-8-trello-doska-ro-yxat-karta" aria-label="Permalink to &quot;2.8. Trello: doska, ro&#39;yxat, karta&quot;">​</a></h3><ul><li><strong>Doska (board)</strong> — butun loyiha, masalan «Sinf gazetasi».</li><li><strong>Ro&#39;yxat (list)</strong> — ustun: <strong>Qilinadi (To Do)</strong>, <strong>Jarayonda (Doing)</strong>, <strong>Bajarildi (Done)</strong>.</li><li><strong>Karta (card)</strong> — bitta vazifa: «Muqova rasmini chizish». Kartaga <strong>ishtirokchi</strong> (kim bajaradi), <strong>muddat</strong>, <strong>tekshiruv ro&#39;yxati (checklist)</strong>, izoh qo&#39;shiladi.</li><li>Ish bajarilishiga qarab karta sichqoncha bilan chapdan o&#39;ngga <strong>sudraladi</strong>.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>| Qilinadi        | Jarayonda          | Bajarildi       |</span></span>
<span class="line"><span>|-----------------|--------------------|-----------------|</span></span>
<span class="line"><span>| Sarlavha tanlash| Maqola yozish (Ali)| Mavzuni tanlash |</span></span>
<span class="line"><span>| Rasm topish     |                    |                 |</span></span></code></pre></div><p>Bunday ustunli usul <strong>Kanban</strong> deb ataladi.</p><h3 id="_2-9-hamkorlikdagi-odob" tabindex="-1">2.9. Hamkorlikdagi odob <a class="header-anchor" href="#_2-9-hamkorlikdagi-odob" aria-label="Permalink to &quot;2.9. Hamkorlikdagi odob&quot;">​</a></h3><ul><li>Hujjatga faqat kerakli odamlarni qo&#39;shing, rollarni to&#39;g&#39;ri bering (11-dars).</li><li>Izohda hurmat bilan yozing: «Bu yerda xato bor» o&#39;rniga «Shu jumlani qisqartirsak bo&#39;ladimi?».</li><li>Muddatlarga rioya qiling: Trello kartasidagi muddat — jamoaga bergan va&#39;dangiz.</li></ul><h3 id="_2-10-butun-rasm" tabindex="-1">2.10. Butun rasm <a class="header-anchor" href="#_2-10-butun-rasm" aria-label="Permalink to &quot;2.10. Butun rasm&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span>Bulut (Drive / OneDrive)</span></span>
<span class="line"><span>  -&gt; onlayn hujjat (Docs, Sheets, Slides | Word, Excel, PowerPoint)</span></span>
<span class="line"><span>       -&gt; ulashish + ruxsat -&gt; birgalikda tahrir, izoh, versiya tarixi</span></span>
<span class="line"><span>  -&gt; vazifalar: To Do / Google Tasks (shaxsiy), Trello (jamoa)</span></span></code></pre></div><hr>`,33))]),i("div",k,[i("h2",y,[r(t,{name:"file-text"}),a[6]||(a[6]=o(" 3. Amaliy mashg'ulotlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-mashg-ulotlar","aria-label":`Permalink to "<Icon name="file-text" /> 3. Amaliy mashg'ulotlar"`},"​",-1))]),a[8]||(a[8]=s('<blockquote><p>Sinf 3–4 kishilik guruhlarga bo&#39;linadi. Har guruhda bitta «sardor» hujjatni yaratib, boshqalarni Muharrir qilib qo&#39;shadi. Akkauntlar bo&#39;lmasa, mentor o&#39;z akkauntida hujjat yaratib, sinf kompyuterlarida ochib beradi yoki ishlar qog&#39;ozda modellashtiriladi.</p></blockquote><h3 id="_1-mashq-oson-moslashtiring" tabindex="-1">1-mashq (oson). Moslashtiring <a class="header-anchor" href="#_1-mashq-oson-moslashtiring" aria-label="Permalink to &quot;1-mashq (oson). Moslashtiring&quot;">​</a></h3><p><strong>Vazifa:</strong> Google xizmatini Microsoft 365 dagi jufti bilan juftlang: Docs, Sheets, Slides, Drive — Excel, OneDrive, Word, PowerPoint.</p><p><strong>Yechim:</strong> Docs — Word; Sheets — Excel; Slides — PowerPoint; Drive — OneDrive.</p><h3 id="_2-mashq-oson-birgalikdagi-hujjat" tabindex="-1">2-mashq (oson). Birgalikdagi hujjat <a class="header-anchor" href="#_2-mashq-oson-birgalikdagi-hujjat" aria-label="Permalink to &quot;2-mashq (oson). Birgalikdagi hujjat&quot;">​</a></h3><p><strong>Vazifa:</strong> Sardor Google Docs da <code>Sinf gazetasi — 4-hafta</code> hujjatini yaratadi va guruhdoshlarni Muharrir qilib qo&#39;shadi. Har bir a&#39;zo o&#39;z ismi bilan bitta bo&#39;lim sarlavhasini yozadi (Yangiliklar, Sport, Texnologiya, Hazil).</p><p><strong>Yechim:</strong> Yangi → Google Docs → nom → Ulashish → emaillar → Muharrir → Yuborish. Tekshirish: o&#39;ng yuqorida barcha a&#39;zolarning avatarlari, hujjatda 4 ta sarlavha.</p><h3 id="_3-mashq-o-rta-izoh-va-javob" tabindex="-1">3-mashq (o&#39;rta). Izoh va javob <a class="header-anchor" href="#_3-mashq-o-rta-izoh-va-javob" aria-label="Permalink to &quot;3-mashq (o&#39;rta). Izoh va javob&quot;">​</a></h3><p><strong>Vazifa:</strong> Har bir a&#39;zo jamoadoshining bo&#39;limidagi bitta jumlani belgilab, hurmat bilan izoh qoldiradi. Muallif izohga javob yozadi va <strong>Hal qilindi</strong> ni bosadi. So&#39;ng <strong>Versiyalar tarixi</strong> ni ochib, kim qanday o&#39;zgartirish qilganini ko&#39;ring.</p><p><strong>Yechim:</strong> Belgilash → Izoh qo&#39;shish (<code>Ctrl + Alt + M</code>) → yozish → Izoh; javob → Hal qilindi. Fayl → Versiyalar tarixi → Versiyalar tarixini ko&#39;rish: o&#39;ng panelda vaqt va ism bo&#39;yicha versiyalar ro&#39;yxati.</p><h3 id="_4-mashq-o-rta-jamoaviy-byudjet-jadvali" tabindex="-1">4-mashq (o&#39;rta). Jamoaviy byudjet jadvali <a class="header-anchor" href="#_4-mashq-o-rta-jamoaviy-byudjet-jadvali" aria-label="Permalink to &quot;4-mashq (o&#39;rta). Jamoaviy byudjet jadvali&quot;">​</a></h3><p><strong>Vazifa:</strong> Google Sheets da gazeta uchun kerakli 4 ta material va narxini yozing, <code>=SUM()</code> bilan jami summani hisoblang. Jadvalni guruhdoshlarga <strong>Ko&#39;ruvchi</strong> qilib ulashing.</p><p><strong>Yechim (namuna):</strong> A2:A5 — materiallar, B2:B5 — narxlar, B6 — <code>=SUM(B2:B5)</code>. Ulashish → Ko&#39;ruvchi (jadvalni faqat sardor o&#39;zgartiradi).</p><h3 id="_5-mashq-qiyin-trello-doskasi" tabindex="-1">5-mashq (qiyin). Trello doskasi <a class="header-anchor" href="#_5-mashq-qiyin-trello-doskasi" aria-label="Permalink to &quot;5-mashq (qiyin). Trello doskasi&quot;">​</a></h3><p><strong>Vazifa:</strong> Trello da (yoki qog&#39;ozda 3 ustun chizib) «Sinf gazetasi» doskasini yarating: Qilinadi, Jarayonda, Bajarildi. Kamida 6 ta karta qo&#39;shing, har biriga mas&#39;ul va muddat yozing. Dars davomida kartalarni ustunlar bo&#39;ylab suring.</p><p><strong>Yechim:</strong> Doska «Sinf gazetasi»; ro&#39;yxatlar Qilinadi/Jarayonda/Bajarildi; kartalar masalan: Mavzu tanlash, Maqola yozish, Rasm topish, Byudjet jadvali, Taqdimot yig&#39;ish, Taqdimotni sinfda ko&#39;rsatish. Har bir kartada mas&#39;ul ism va sana. Dars oxirida kamida 3 ta karta «Bajarildi» da bo&#39;lsin.</p><h3 id="_6-mashq-bonus-vositani-tanlang" tabindex="-1">6-mashq (bonus). Vositani tanlang <a class="header-anchor" href="#_6-mashq-bonus-vositani-tanlang" aria-label="Permalink to &quot;6-mashq (bonus). Vositani tanlang&quot;">​</a></h3><p><strong>Vazifa:</strong> Har bir holatga mos vositani tanlang (To Do, Google Tasks, Trello) va sababini yozing: (a) har kuni uy vazifalarini belgilab borish; (b) 5 kishilik guruh loyihasini kim nima qilayotganini kuzatish; (c) Gmail dagi xatdan vazifa yaratib, uni kalendarda ko&#39;rish.</p><p><strong>Yechim:</strong> (a) Microsoft To Do yoki Google Tasks — shaxsiy ro&#39;yxat; (b) Trello — jamoaviy doska va kartalarda mas&#39;ullar; (c) Google Tasks — Gmail va Calendar bilan bog&#39;langan.</p><hr>',20))]),i("div",c,[i("h2",v,[r(t,{name:"file-text"}),a[9]||(a[9]=o(" 4. Tezkor savollar (Checklist) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-savollar-checklist","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor savollar (Checklist)"'},"​",-1))]),a[11]||(a[11]=s("<ol><li>Onlayn hujjatning oddiy fayldan asosiy afzalligi nima? <ul><li><strong>Javob:</strong> Brauzerda ishlaydi, avtomatik saqlanadi va bir necha kishi bir vaqtda tahrirlaydi.</li></ul></li><li>Google Slides ning Microsoft 365 dagi jufti qaysi? <ul><li><strong>Javob:</strong> PowerPoint.</li></ul></li><li>Izoh va oddiy tahrirning farqi nima? <ul><li><strong>Javob:</strong> Izoh matnni o&#39;zgartirmaydi, faqat yonida fikr yoki savol qoldiradi.</li></ul></li><li>Jamoadosh matnni xato o&#39;chirib yuborsa, nima qilasiz? <ul><li><strong>Javob:</strong> Fayl → Versiyalar tarixi orqali oldingi versiyani tiklayman.</li></ul></li><li>Trello da doska, ro&#39;yxat va karta nima? <ul><li><strong>Javob:</strong> Doska — loyiha, ro&#39;yxat — ustun (bosqich), karta — bitta vazifa.</li></ul></li></ol>",1))]),i("div",q,[i("h2",p,[r(t,{name:"file-text"}),a[12]||(a[12]=o(" 5. Kuchli o'quvchi uchun qo'shimcha ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-kuchli-o-quvchi-uchun-qo-shimcha","aria-label":`Permalink to "<Icon name="file-text" /> 5. Kuchli o'quvchi uchun qo'shimcha"`},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,[o("Google Docs da "),i("strong",null,"Taklif rejimi"),o(" ni yoqib, jamoadosh matniga 2 ta taklif yozing; muallif ularni qabul qilsin yoki rad etsin.")]),i("li",null,[o("Trello kartasiga "),i("strong",null,"tekshiruv ro'yxati (checklist)"),o(" qo'shing va bajarilish foizi qanday o'zgarishini kuzating.")])],-1))]),i("div",f,[i("h2",j,[r(t,{name:"file-text"}),a[15]||(a[15]=o(" 6. Mentor uchun eslatmalar ",-1)),a[16]||(a[16]=i("a",{class:"header-anchor",href:"#_6-mentor-uchun-eslatmalar","aria-label":'Permalink to "<Icon name="file-text" /> 6. Mentor uchun eslatmalar"'},"​",-1))]),a[17]||(a[17]=i("ul",null,[i("li",null,"Guruhlar hujjatlarini darsdan oldin tayyor shablon sifatida berish vaqtni tejaydi."),i("li",null,"Trello uchun akkaunt kerak; vaqt yoki internet yetmasa, doska qog'ozda (3 ustun + stikerlar) bajariladi — g'oya bir xil."),i("li",null,[o("Dasturda formulalar chuqur o'rganilmaydi: Sheets da faqat "),i("code",null,"=SUM()"),o(" bilan cheklaning.")]),i("li",null,"Dars oxirida akkauntlardan chiqish va keraksiz ulashishlarni olib tashlashni eslating (11-dars qoidalari).")],-1))])])}const B=l(h,[["render",z]]);export{P as __pageData,B as default};
